    pervideo=read(BASE/'test_per_video.json')
    errors=read(BASE/'error_analysis.json')
    def result(name,k=1): return next(r for r in summary if r['method']==name and r['k']==k)
    v,t,f=result('visual_cos'),result('text_mlp_s2027_full'),result('fusion_s2027')
    practical=f['fpr']<v['fpr'] and f['tpr']>=frozen['budgets']['1']['recall']
    decision=('Получен наблюдаемый компромисс в пользу совместной метрики по заранее заданным условиям.' if practical else 'Заранее заданные условия полезного превосходства совместной метрики не выполнены.')
    inference=('Направленный знаковый тест отвергает H0 при 0,05.' if stats['sign_test_p']<.05 else 'Направленный знаковый тест не отвергает H0 при 0,05; это не доказательство равенства методов.')
    overview=(f'На 14 отложенных видео семи категорий при одном эталоне визуальный косинус дал полноту {pct(v["tpr"])}% и долю принятия чужих экземпляров {pct(v["fpr"])}%. '
              f'Авторский текстовый MLP с полной ковариацией дал {pct(t["tpr"])}% и {pct(t["fpr"])}%; совместная метрика - {pct(f["tpr"])}% и {pct(f["fpr"])}%. '
              f'Ориентир полноты, вычисленный на валидации, равен {pct(frozen["budgets"]["1"]["recall"])}%. {decision}')
    stat_text=(f'Снижение FPR совместной метрики относительно визуального косинуса: {pct(stats["fpr_reduction"])} п.п.; парный bootstrap 95% {interval(stats["fpr_reduction_ci95"])} п.п. '
               f'Разность полноты: {pct(stats["recall_difference"])} п.п., интервал {interval(stats["recall_difference_ci95"])} п.п. '
               f'Одностороннее p={stats["sign_test_p"]:.4f}; равенств {stats["tie_videos"]} из 14. {inference}')
